    Bug 1948154 - Prevent the account settings from triggering the load event twice. r=darktrojan

    Differential Revision: https://phabricator.services.mozilla.com/D238132

diff --git a/mailnews/base/prefs/content/AccountManager.js b/mailnews/base/prefs/content/AccountManager.js
index 8a0e8959132..f5106fe5c83 100644
--- a/mailnews/base/prefs/content/AccountManager.js
+++ b/mailnews/base/prefs/content/AccountManager.js
@@ -102,6 +102,14 @@ var currentPageId;
 var pendingAccount;
 var pendingPageId;

+/**
+ * Track if the tab has already been loaded and we're only refreshing it after a
+ * new account selection.
+ *
+ * @type {boolean}
+ */
+var hasLoaded = false;
+
 /**
  * This array contains filesystem folders that are deemed inappropriate
  * for use as the local directory pref for message storage.
@@ -187,14 +195,22 @@ function onLoad() {
         });
       }
     }
-    UIFontSize.registerWindow(contentFrame.contentWindow);
+    if (!hasLoaded) {
+      UIFontSize.registerWindow(contentFrame.contentWindow);
+      // TODO: Add the density registration once the account settings style is
+      // updated to support density variations.
+    }
   });

-  UIDensity.registerWindow(window);
-  UIFontSize.registerWindow(window);
+  if (!hasLoaded) {
+    UIDensity.registerWindow(window);
+    UIFontSize.registerWindow(window);
+    hasLoaded = true;
+  }
 }

 function onUnload() {
+  hasLoaded = false;
   gAccountTree.unload();
 }

@@ -1631,6 +1647,10 @@ var gAccountTree = {
   ]),

   async load() {
+    if (hasLoaded) {
+      return;
+    }
+
     await FolderTreeProperties.ready;

     this._build();
